"""Переводы интерфейса: лаунчер, установщик, оболочка Helper.

Ключ — ровно та русская строка, что стоит в коде (как ``msgid`` в gettext), а
значения — переводы по кодам языков сайта (``locale_config.SUPPORTED_LOCALES``).
Русского словаря нет: оригинал и есть перевод по умолчанию, поэтому забытый
ключ показывает русскую строку, а не пустоту и не имя ключа.

Одна запись держит все языки рядом, а :data:`CATALOGS` разворачивается в
привычный вид «язык → {строка: перевод}»: так переводчику видно одну строку во
всех языках и не бывает расхождений в наборе ключей между языками.

Файл лежит в корне ``uploader/``, потому что пакет обновлений собирается из
плоского списка ``*.py`` (``build_bundle.bundle_files``): подкаталоги и
``.mo``-файлы до установленных копий не доезжают.
"""
