def _build_catalogs() -> Dict[str, Dict[str, str]]:
    """Развернуть «строка → {язык: текст}» в «язык → {строка: текст}»."""
    catalogs: Dict[str, Dict[str, str]] = {}
    for source, translations in _STRINGS.items():
        for code, text in translations.items():
            catalogs.setdefault(str(code), {})[str(source)] = str(text)
    return catalogs


#: Язык → словарь переводов. Русского нет: им служит сам оригинал.
CATALOGS: Dict[str, Dict[str, str]] = _build_catalogs()

__all__ = ["CATALOGS"]
